const body = $input.first().json.body;
const data = body?.data || {};
const msg  = data?.message || {};

let text = '';
if      (msg.conversation)                                               text = msg.conversation;
else if (msg.extendedTextMessage?.text)                                  text = msg.extendedTextMessage.text;
else if (msg.buttonsResponseMessage?.selectedButtonId)                   text = msg.buttonsResponseMessage.selectedButtonId;
else if (msg.listResponseMessage?.singleSelectReply?.selectedRowId)      text = msg.listResponseMessage.singleSelectReply.selectedRowId;
else if (msg.imageMessage?.caption)                                      text = msg.imageMessage.caption || '[image sent]';
else                                                                     text = '[unsupported message type]';

const remoteJid = data.key?.remoteJid || '';
const phone     = remoteJid.replace('@s.whatsapp.net', '').replace('@c.us', '');

return [{
  json: {
    remoteJid,
    phone,
    pushName:    data.pushName || 'Customer',
    messageType: data.messageType || 'conversation',
    instance:    body.instance || '',
    text:        text.trim()
  }
}];

const output = $input.first().json.output || '';

const cleaned = output
  .replace(/^#+\s/gm, '')
  .replace(/^---+$/gm, '')
  .replace(/\*\*(.*?)\*\*/g, '*$1*')
  .replace(/__(.*?)__/g, '_$1_')
  .trim();

return [{
  json: {
    ...$input.first().json,
    formattedOutput: cleaned
  }
}];
